-- Tabla de calificacion historica de riesgo (BUPC agregada). Claves normalizadas: MAYUSCULAS sin acentos.
create table if not exists public.riesgo_historico (
  id bigserial primary key,
  pretension text not null,
  clase_pretension text,  -- null = respaldo por pretension
  n integer not null,
  criterios jsonb not null,
  updated_at timestamptz default now()
);
create unique index if not exists riesgo_hist_pret_clase on public.riesgo_historico (pretension, coalesce(clase_pretension,''));
alter table public.riesgo_historico enable row level security;
drop policy if exists riesgo_hist_read on public.riesgo_historico;
create policy riesgo_hist_read on public.riesgo_historico for select using (true);
truncate public.riesgo_historico;
